from psyclone.transformations import (
    Dynamo0p3RedundantComputationTrans,
    Dynamo0p3AsyncHaloExchangeTrans,
    DynamoOMPParallelLoopTrans,
    DynamoOMPColourTrans,
    KernelModuleInlineTrans,
    TransformationError
)
from psyclone.core import NoInvokesError
from psyclone.domain.lfric import LFRicConstants

# Boolean variables to control transformations
APPLY_REDUNDANT_COMPUTATION = True
APPLY_ASYNC_HALO_EXCHANGE = True
APPLY_OMP_COLOURING = True
APPLY_INTRINSIC_INLINING = True

def apply_transformations(psy):
    """Apply a series of transformations to all invokes in the given psy object."""
    rc_trans = Dynamo0p3RedundantComputationTrans()
    async_hex_trans = Dynamo0p3AsyncHaloExchangeTrans()
    omp_colour_trans = DynamoOMPColourTrans()
    inline_trans = KernelModuleInlineTrans()

    try:
        invokes = psy.invokes.invoke_list
    except NoInvokesError:
        return psy

    for invoke in invokes:
        schedule = invoke.schedule
        if schedule is None:
            continue

        # Apply redundant computation transformation
        if APPLY_REDUNDANT_COMPUTATION:
            try:
                for loop in schedule.loops():
                    rc_trans.apply(loop)
            except TransformationError:
                pass

        # Apply asynchronous halo exchange transformation
        if APPLY_ASYNC_HALO_EXCHANGE:
            try:
                for hex_node in schedule.walk('HaloExchange'):
                    async_hex_trans.apply(hex_node)
            except TransformationError:
                pass

        # Apply OpenMP colouring transformation
        if APPLY_OMP_COLOURING:
            try:
                for loop in schedule.loops():
                    if loop.loop_type == LFRicConstants.COLOUR_LOOP_TYPE:
                        omp_colour_trans.apply(loop)
            except TransformationError:
                pass

        # Apply intrinsic inlining transformation
        if APPLY_INTRINSIC_INLINING:
            try:
                for kern_call in schedule.walk('Kern'):
                    inline_trans.apply(kern_call)
            except TransformationError:
                pass

    return psy
